function identificarBancoCartao(cartao) {
  const nome = (cartao.nome || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  if (/\bnu\s*bank\b|\bnu\b/.test(nome)) return "nubank";
  if (/\binter\b/.test(nome)) return "inter";
  if (/\bc\s*6\s*(?:bank)?\b/.test(nome)) return "c6";
  if (/\bmercado\s*pago\b/.test(nome)) return "mercadopago";
  if (/\bitau\b/.test(nome)) return "itau";
  if (/\bsantander\b/.test(nome)) return "santander";
  if (/\bpic\s*pay\b/.test(nome)) return "picpay";
  return cartao.id === "nubank" ? "nubank" : null;
}

